from pathlib import Path
import json,shutil,sys
base=Path(__file__).resolve().parent.parent
src=Path(sys.argv[1]);out=base/'Captures';out.mkdir(exist_ok=True)
proof=base/'QA/Witnesses';proof.mkdir(exist_ok=True)
for p in src.glob('Mechanics_Round_*.png'):shutil.copy2(p,out/p.name)
for p in src.glob('*Witness.json'):shutil.copy2(p,proof/p.name)
rounds=[json.loads((src/('Round'+str(i)+'_Witness.json')).read_text()) for i in range(1,6)]
options=''.join('<option value="'+str(i)+'">'+str(i)+' · '+r['title']+'</option>' for i,r in enumerate(rounds,1))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gameplay Mechanics R4 · Round playtest</title>
<style>body{margin:0;background:#0b121c;color:#ecdcb9;font:17px/1.55 system-ui}main{max-width:960px;margin:auto;padding:24px}h1{font-size:28px;color:#e1bd74}a{color:#9dd1f0}select{background:#172638;color:#f6e7c3;border:1px solid #9a7741;border-radius:6px;padding:10px;font:inherit;max-width:100%;margin:4px 0}#capture{display:block;width:min(100%,576px);height:auto;margin:20px auto;border:1px solid #8b703e}.note{color:#afbed0;font-size:14px}details{border-top:1px solid #415068;margin-top:24px;padding-top:16px}.tools{display:flex;flex-wrap:wrap;gap:12px}code{overflow-wrap:anywhere}</style>
<main><h1>Gameplay Mechanics R4 · Round playtest</h1><p>Five short rounds to review line creation, layered ice, Spark creation, seals and mixed objectives on the approved gameplay page. Inventory boosters are unavailable in this mode.</p>
<div class="tools"><label>Round <select id="round">OPTIONS</select></label><label>State <select id="state"><option value="Start">Start</option><option value="Win">Verified win</option><option value="Fail" id="failure">Move exhaustion (round 5)</option></select></label></div>
<p id="budget"></p><img id="capture" src="Captures/Mechanics_Round_1_Start.png" alt="Actual Unity round playtest capture">
<p class="note">Actual Unity captures at576×1280, one portrait at a time. Developer controls are not production UI. These are short prototype rounds, not shipped campaign levels. No human difficulty rating or win rate is claimed.</p>
<details open><summary>Play in Unity</summary><p>Enter Play Mode, reach Home and close any modal. Choose <b>Legends of Rus → Development → Gameplay Mechanics Sandbox</b>. It opens with Round1. Next changes rounds; Retry restores the exact board and move budget. Fixtures switches to the earlier mechanics laboratory; Rounds returns here. Exit returns Home. No campaign progress or rewards are written.</p></details>
<details><summary>Recorded winning path · spoilers</summary><p>One verified solution, not necessarily the shortest. Coordinates count columns from the left and rows from the top, starting at1. Introductory line/Spark witnesses begin with their teaching move.</p><ol id="actions"></ol><a id="witness" href="QA/Witnesses/Round1_Witness.json">Full deterministic replay witness</a></details>
<details><summary>What to review next</summary><p>Can you identify the target obstacles and remaining layers without the solution? Are line direction, Spark landing and bomb footprints readable during cascades? Does the move allowance offer useful choices? Test several human attempts before adjusting budgets further or expanding campaign content.</p></details>
<p><a href="ImplementationReport.md">Implementation report</a> · <a href="QA/Verification.json">Test results</a> · <a href="QA/Scope.json">Changed files</a></p></main>
<script>const rounds=DATA;const round=document.querySelector('#round'),state=document.querySelector('#state');function show(){if(state.value==='Fail')round.value='5';const i=+round.value,r=rounds[i-1];document.querySelector('#capture').src='Captures/Mechanics_Round_'+i+'_'+state.value+'.png';document.querySelector('#budget').textContent=r.moveLimit+' moves available · recorded winning path: '+r.solutionMoves+' moves · inventory boosters: 0';document.querySelector('#actions').replaceChildren(...r.commands.map(a=>{const li=document.createElement('li');li.textContent=a.Tap?'Tap ('+(a.X+1)+', '+(a.Y+1)+')':'Swap ('+(a.X+1)+', '+(a.Y+1)+') → ('+(a.ToX+1)+', '+(a.ToY+1)+')';return li}));document.querySelector('#witness').href='QA/Witnesses/Round'+i+'_Witness.json'}round.onchange=()=>{if(state.value==='Fail')state.value='Start';show()};state.onchange=show;show();</script></html>'''
(base/'Gameplay_Mechanics_R4_Review.html').write_text(html.replace('OPTIONS',options).replace('DATA',json.dumps(rounds,ensure_ascii=False)))
